from ortools.sat.python import cp_model
import json

def main():
    P = list(range(1, 26))
    volume = {
        1: 30, 2: 25, 3: 35, 4: 20, 5: 40,
        6: 15, 7: 45, 8: 10, 9: 50, 10: 5,
        11: 30, 12: 25, 13: 35, 14: 20, 15: 40,
        16: 15, 17: 45, 18: 10, 19: 50, 20: 5,
        21: 20, 22: 15, 23: 30, 24: 25, 25: 10
    }
    capacity = 100
    M = 25

    model = cp_model.CpModel()

    x = {}
    for i in P:
        for t in range(1, M + 1):
            x[(i, t)] = model.NewBoolVar(f"x_{i}_{t}")

    y = {}
    for t in range(1, M + 1):
        y[t] = model.NewBoolVar(f"y_{t}")

    for i in P:
        model.Add(sum(x[(i, t)] for t in range(1, M + 1)) == 1)

    for t in range(1, M + 1):
        model.Add(sum(volume[i] * x[(i, t)] for i in P) <= capacity)

    for t in range(1, M + 1):
        for i in P:
            model.Add(x[(i, t)] <= y[t])

    for t in range(1, M):
        model.Add(y[t] >= y[t + 1])

    model.Minimize(sum(y[t] for t in range(1, M + 1)))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        num_trucks = sum(solver.Value(y[t]) for t in range(1, M + 1))

        truck_loads_list = []
        for t in range(1, M + 1):
            if solver.Value(y[t]) == 1:
                parcels_in_truck = []
                for i in P:
                    if solver.Value(x[(i, t)]) == 1:
                        parcels_in_truck.append(i)
                if parcels_in_truck:
                    truck_loads_list.append(parcels_in_truck)

        print(json.dumps({
            "num_trucks": num_trucks,
            "truck_loads": truck_loads_list
        }))
    else:
        print(json.dumps({
            "num_trucks": 0,
            "truck_loads": []
        }))

if __name__ == "__main__":
    main()
